local _, Private = ...
local L = Private.L

local DecodeBase64 = C_EncodingUtil.DecodeBase64
local DecompressString = C_EncodingUtil.DecompressString
local DeserializeCBOR = C_EncodingUtil.DeserializeCBOR

local _G = _G

-- Deadly Boss Mods profile
function Private:Setup_DBM(installer)
	if not Private.IsAddOnLoaded('DBM-Core') then Private:Print('Deadly Boss Mods ' .. L["is not installed or enabled."]) return end

	-- Profile name
	local name = 'Luckyone'

	-- Profile string
	local importString = [[]]

	-- No import API, export string is base64
	local data = DeserializeCBOR(DecompressString(DecodeBase64(importString)))

	-- Skip retail setup popup
	data.DBM.HasShownMidnightPopup = true

	-- The "Run Away" sound file is missing on vanilla, let it fill defaults
	if Private.isClassic then
		data.DBM.SpecialWarningSound4 = nil
	end

	-- 1080p
	local scaled = Private.Addon.db.global.scaled
	if scaled then
		data.DBT.DBM.TimerY = -106.5 -- 1440p: -165.5
		data.DBM.InfoFrameX = 475.5 -- 1440p: 575.5
		data.DBM.RangeFrameRadarX = -495 -- 1440p: -585
	end

	-- Profile import, overwrites an existing profile with that name
	_G.DBM_AllSavedOptions[name] = data.DBM
	_G.DBT_AllPersistentOptions[name] = data.DBT
	_G.DBM:ApplyProfile(name)

	-- Minimap icon
	if _G.DBM_MinimapIcon then
		_G.DBM_MinimapIcon.hide = true
	end
	Private.Libs.LDBI:Hide('DBM')

	Private:Print(L["Deadly Boss Mods profile has been set."], installer)
end
